// Fixed-control fixture: Dice locks preserve selected timing/style/division under test.
#define GROOVE_DICE_TEST
#include "../src/GrooveDice.cpp"
#include <cassert>
#include <iostream>
#include <tuple>
#include <memory>
using Row=std::tuple<int,int,int,int,int>;
static thread_local bool guarded=false;
#if !__has_feature(address_sanitizer)
void*operator new(size_t n){if(guarded)std::abort();if(auto*p=std::malloc(n))return p;throw std::bad_alloc();}
void operator delete(void*p)noexcept{std::free(p);}
#endif
struct RuleProbe{static auto events(GrooveDice&p,double ppq){std::vector<std::tuple<int,int,int,int>>v;for(int i=0;i<p.eventCount;++i){auto&e=p.events[i];double beat=ppq+e.offset*120./(60*44100);v.emplace_back(int(std::floor((beat+1.e-8)/4)),int(std::lround(std::fmod(beat+1.e-8,4.)*960))%3840,e.role,e.velocity);}return v;}};
struct Host{GrooveDice p;float data[16][512]{},*out[16];double ppq=0;bool playing=false;int frames=128;std::vector<std::tuple<int,int,int,int>> events;
 Host(){for(int c=0;c<16;++c)out[c]=data[c];p.prepare(44100,512);p.reset();for(int n=0;n<16;++n)p.set(kDiceLock0+n,1);p.set(kKitLock,1);p.set(kScope,1);for(int k:{kGhost,kRndNudge,kSnareLate,kHatShift,kVelSpread,kVariation})p.set(k,0);p.set(kSwing,50);p.set(kRandomAmt,100);block();}
 void block(){for(auto&c:data)std::fill(c,c+512,0);mpc::ProcessContext c{};c.outputs=out;c.numOutputs=16;c.numFrames=frames;c.sampleRate=44100;c.transport.valid=c.transport.ppqValid=c.transport.tempoValid=true;c.transport.playing=playing;c.transport.bpm=120;c.transport.ppqPos=ppq;guarded=true;p.process(c);guarded=false;auto e=RuleProbe::events(p,ppq);events.insert(events.end(),e.begin(),e.end());if(playing)ppq+=frames*120./(60*44100);}
 void pulse(int key){p.set(key,!p.getBool(key));block();}
 void until(double end){while(ppq<end)block();}
 auto notes(int b,int group=-1){std::vector<Row>v;for(auto&cell:p.notes[b])if(cell.valid()){auto n=cell.read();int g=n.role<2?n.role:n.role<4?2:3;if(group<0||g==group)v.emplace_back(n.tick,n.role,n.velocity,n.chance,n.gate);}return v;}
};
int main(){
 {Host h;auto&p=h.p;for(int n=0;n<100;++n){h.pulse(kRoll);assert(p.lengths[4].load()==3840);int snare=0;for(auto&c:p.notes[4])if(c.valid()){auto n=c.read();assert(n.tick<3840);if(n.role==0)assert(n.tick!=960&&n.tick!=2880);if(n.role==1&&n.velocity>70){assert(n.tick==960||n.tick==2880);++snare;}}assert(snare==2);}h.events.clear();h.playing=true;h.until(32);std::vector<std::tuple<int,int,int>>expected;for(auto [bar,tick,role,vel]:h.events)if(bar==1)expected.emplace_back(tick,role,vel);assert(!expected.empty());for(int b=2;b<7;++b){std::vector<std::tuple<int,int,int>>actual;for(auto [bar,tick,role,vel]:h.events)if(bar==b)actual.emplace_back(tick,role,vel);assert(actual==expected);}std::cout<<"PASS100one-bar ROLLs; identical repeated MIDI hits over6bars, backbeat2/4, no bar-dependent response patterns\n";}
 {Host h;auto&p=h.p;h.pulse(kRoll);h.playing=true;h.until(1.2);auto kick=h.notes(4,0),snare=h.notes(4,1),perc=h.notes(4,3);auto rolls=p.diceRolls.load();p.set(kHatRhythm,6);h.block();assert(((p.getInt(kHatPhraseState)&15)-1)==6);assert(h.notes(4,2).size()==16);assert(h.notes(4,0)==kick&&h.notes(4,1)==snare&&h.notes(4,3)==perc);assert(p.diceRolls.load()==rolls);p.setNormalised(kQ13,3/14.f);h.block();assert(h.notes(4,2).size()==8);p.setNormalised(kQ5,3/6.f);h.block();assert(p.getInt(kRuleKickStyle)==4&&h.notes(4,0).size()==1);assert(h.notes(4,1)==snare);rolls=p.diceRolls.load();h.pulse(kRoll);assert(p.diceRolls.load()==rolls+1&&!p.pendingRoll.load());std::cout<<"PASS mid-bar Division/Q-Link/style edits update in one block, preserve other parts and never fire Dice; ROLL immediate\n";}
 {Host h;auto&p=h.p;h.pulse(kRoll);auto rhythm=h.notes(4,0);p.set(kRuleKickStyle,0);h.block();for(int n=0;n<20;++n)h.pulse(kRoll);assert(h.notes(4,0)==rhythm);auto fill=h.notes(0);h.pulse(kRoll);assert(h.notes(0)==fill);std::cout<<"PASS LOCK holds part; main Dice preserves recorded fill A\n";}
 {Host h;auto&p=h.p;for(int g=0;g<4;++g){assert(p.proxyTarget(4+g)==kRulePickKick+g);assert(p.param(kRuleKickStyle+g).choices.size()==8);for(int style=1;style<8;++style){auto other=h.notes(4,(g+1)%4);p.set(kRuleKickStyle+g,style);h.block();assert(p.getInt(kRuleKickStyle+g)==style&&p.lengths[4].load()==3840);assert(h.notes(4,(g+1)%4)==other);}}p.set(kRuleKickStyle,6);p.set(kUserKit,0);h.pulse(kSaveKit);p.set(kRuleKickStyle,7);h.block();h.pulse(kLoadKit);assert(p.getInt(kRuleKickStyle)==7);p.selectFactoryProgram(3);h.block();assert(p.getInt(kRuleKickStyle)==7);auto state=p.internalSaveState();Host restored;assert(restored.p.internalLoadState(state.data(),state.size()));restored.p.reset();restored.block();assert(restored.p.getInt(kRuleKickStyle)==7&&restored.p.internalSaveState()==state);std::cout<<"PASS32role styles, per-part edits, factory/user kits preserve rules, saved state byte-identical\n";}
 {Host h;auto&p=h.p;h.pulse(kRoll);auto a=h.notes(4);auto seed=p.partSeed[0].load();h.pulse(kRoll);h.pulse(kUndo);assert(h.notes(4)==a&&p.partSeed[0].load()==seed);std::cout<<"PASS immediate ROLL Undo restores complete prior one-bar loop and seed\n";}
 {Host h;h.p.set(kRuleHatStyle,1);h.p.set(kHatRhythm,0);h.block();h.pulse(kRoll);h.playing=true;h.until(1.1);auto dice=h.p.diceRolls.load();h.p.set(kHatRhythm,6);h.block();h.until(2.95);bool sixteenth=false;for(auto [bar,tick,role,vel]:h.events)if(bar==0&&tick==1200&&role==2)sixteenth=true;assert(sixteenth&&h.p.diceRolls.load()==dice);std::cout<<"PASS actual scheduler delivers new16th note atbeat1.25 immediately after mid-bar Division edit\n";}
 // 1.1 saved states have521 parameters and the same layer trailer size.
 {Host h;h.p.set(kRuleKickStyle,7);h.p.set(kL0Level,-19);h.block();h.pulse(kRoll);auto expected=h.notes(4);auto state=h.p.internalSaveState();size_t pos=12;for(int n=0;n<521;++n)pos+=1+state[pos]+8;size_t tail=pos;for(int n=521;n<kParamCount;++n)tail+=1+state[tail]+8;std::vector<uint8_t>old(state.begin(),state.begin()+pos);old.insert(old.end(),state.begin()+tail,state.end());for(int n=0;n<4;++n)old[8+n]=uint8_t(521>>(n*8));Host restored;assert(restored.p.internalLoadState(old.data(),old.size()));restored.p.reset();restored.block();assert(restored.p.getInt(kRuleKickStyle)==3&&std::abs(restored.p.get(kL0Level)+19)<.0001f&&restored.notes(4)==expected);std::cout<<"PASS521-param old-state migration retains layers/notes; legacy rule IDs/ranges unchanged\n";}
 // Recorded fills play all hits, replace MAIN only for their window, then return to the same loop.
 for(int length:{960,1920,3840,7680,15360}){Host h;auto&p=h.p;h.pulse(kRoll);auto main=h.notes(4);for(auto&c:p.notes[0])c.data.store(0);p.lengths[0].store(length);p.notes[0][0].write({0,7,77,100,80});p.notes[0][1].write({length-240,7,79,100,80});h.playing=true;h.until(.5);h.pulse(kTrigger);h.until(4+length/960.+4);int a=0,b=0;for(auto [bar,tick,role,vel]:h.events){if(vel==77)++a;if(vel==79)++b;}assert(a==1&&b==1&&h.notes(4)==main&&p.recordState.load()==0);}
 std::cout<<"PASS recorded fills1beat..4bars trigger once at next bar, preserve every recorded hit and restore same MAIN loop\n";
 {Host h;auto&p=h.p;h.pulse(kRoll);for(auto&c:p.notes[0])c.data.store(0);p.lengths[0].store(7680);p.notes[0][0].write({0,7,77,100,80});p.notes[0][1].write({7440,7,79,100,80});p.set(kFillEvery,1);h.playing=true;h.until(20);bool first=false,last=false,mainAfter=false;for(auto [bar,tick,role,vel]:h.events){if(bar==2&&tick==0&&vel==77)first=true;if(bar==3&&tick==3600&&vel==79)last=true;if(bar==4&&role==0)mainAfter=true;}assert(first&&last&&mainAfter);std::cout<<"PASS2-bar automatic fill plays its full length before4-bar boundary and MAIN resumes\n";}
}
